"style":{"fontStyle":"italic"}}],"text":"SPIRIT"},"spirit.spiritManifesto.text3":{"runs":[{"end":3,"start":0,"style":{"fontWeight":700}}],"text":"art"}}},"textLayouts":{"mobile":{"spirit.spiritHero.text9":{"offsetX":-113.2,"offsetY":33.3},"spirit.spiritHero.text11":{"offsetX":-11.9,"offsetY":-1.3},"spirit.motetMeaning.english2":{"offsetX":-2.2,"offsetY":65.2},"spirit.motetMeaning.englishTitle":{"offsetX":3.6,"offsetY":61.7}},"tablet":{"spirit.spiritHero.text8":{"offsetX":-8.4,"offsetY":1.6},"spirit.spiritHero.text9":{"offsetX":-119.8,"offsetY":38.2},"spirit.spiritHero.text11":{"offsetX":-6.8,"offsetY":0.8},"spirit.motetMeaning.english2":{"offsetX":-6.5,"offsetY":67.2},"spirit.motetMeaning.englishTitle":{"offsetX":-6.4,"offsetY":57.7}},"desktop":{"spirit.intro.title":{"offsetX":-27.8,"offsetY":31.5},"spirit.closingCta.text1":{"offsetX":7.8,"offsetY":1.3},"spirit.closingCta.text3":{"offsetX":-4.9,"offsetY":4.8},"spirit.closingCta.text4":{"offsetX":106.8,"offsetY":-32.7},"spirit.spiritHero.text2":{"offsetX":27.5,"offsetY":19},"spirit.spiritHero.text3":{"offsetX":-3.5,"offsetY":3.7},"spirit.spiritHero.text4":{"offsetX":130.7,"offsetY":-10},"spirit.spiritHero.text5":{"offsetX":122.2,"offsetY":-15.2},"spirit.valuesSection.text2":{"offsetX":0.9,"offsetY":-13.7},"spirit.valuesSection.text3":{"offsetX":7.8,"offsetY":-18.2},"spirit.valuesSection.text4":{"offsetX":-9,"offsetY":-24.3},"spirit.valuesSection.text5":{"offsetX":250.5,"offsetY":-79.2},"spirit.motetMeaning.english2":{"offsetX":-1.4,"offsetY":42},"spirit.motetMeaning.englishTitle":{"offsetX":1,"offsetY":44.2}}},"schemaVersion":1}}]$reviewed_copy_20261002$::jsonb) loop
    perform pg_advisory_xact_lock(hashtextextended('sample-english-editor:' || (item->>'page'),0));
    select * into original from public.site_editor_pages where page_key=item->>'page' for update;
    if not found or original.version<>(item->>'sourceVersion')::bigint
      or original.draft is distinct from item->'sourceDraft'
      or original.published is distinct from item->'sourcePublished' then
      raise exception 'Korean source changed; no translations were applied: %', item->>'page';
    end if;
    select * into english from public.sample_english_editor_pages where page_key=item->>'page' for update;
    if (found and (english.version<>(item->>'englishVersion')::bigint
      or english.draft is distinct from item->'englishDraft'
      or english.published is distinct from item->'englishPublished'))
      or (not found and (item->>'englishVersion')::bigint<>0) then
      raise exception 'English editor changed; no translations were applied: %', item->>'page';
    end if;
    draft_doc := coalesce(english.draft,empty_doc);
    published_doc := coalesce(english.published,empty_doc);
    for device in select jsonb_object_keys(item->'deviceCopy') loop
      patch := item->'deviceCopy'->device;
      draft_doc := jsonb_set(draft_doc,array['deviceCopy',device],coalesce(draft_doc#>array['deviceCopy',device],'{}'::jsonb)||patch,true);
      published_doc := jsonb_set(published_doc,array['deviceCopy',device],coalesce(published_doc#>array['deviceCopy',device],'{}'::jsonb)||patch,true);
      -- No unrelated device key may disappear or be changed.
      existing_copy := coalesce(coalesce(english.draft,empty_doc)#>array['deviceCopy',device],'{}'::jsonb);
      if ((draft_doc#>array['deviceCopy',device]) - array(select jsonb_object_keys(patch)))
        is distinct from (existing_copy - array(select jsonb_object_keys(patch))) then
        raise exception 'Unrelated English device copy changed';
      end if;
    end loop;
    if (draft_doc-'deviceCopy') is distinct from (coalesce(english.draft,empty_doc)-'deviceCopy')
      or (published_doc-'deviceCopy') is distinct from (coalesce(english.published,empty_doc)-'deviceCopy') then
      raise exception 'English styles, layout or shared copy changed';
    end if;
    perform public.validate_site_editor_document(draft_doc);
    perform public.validate_site_editor_document(published_doc);
    stamp := clock_timestamp();
    if english.published is not null then
      insert into public.sample_english_editor_revisions(page_key,document,published_at,published_by)
      select english.page_key,english.published,english.published_at,english.updated_by
      where not exists(select 1 from public.sample_english_editor_revisions r
        where r.page_key=english.page_key and r.document=english.published and r.published_at=english.published_at);
    end if;
    if english.page_key is null then
      insert into public.sample_english_editor_pages(page_key,draft,published,version,updated_at,published_at,updated_by)
      values(item->>'page',draft_doc,published_doc,2,stamp,stamp,null);
    else
      update public.sample_english_editor_pages set draft=draft_doc,published=published_doc,
        version=version+2,updated_at=stamp,published_at=stamp,updated_by=null where page_key=english.page_key;
    end if;
    insert into public.sample_english_editor_revisions(page_key,document,published_at,published_by)
    values(item->>'page',published_doc,stamp,null);
    if (select draft from public.site_editor_pages where page_key=item->>'page') is distinct from original.draft
      or (select published from public.site_editor_pages where page_key=item->>'page') is distinct from original.published
      or (select version from public.site_editor_pages where page_key=item->>'page')<>original.version then
      raise exception 'Korean document changed';
    end if;
    changed := changed+1;
  end loop;
  if changed<>3 then raise exception 'Expected exactly three English pages'; end if;
end;
$refresh$;
select page_key,version,published->'deviceCopy'->'desktop' as reviewed_desktop_copy,
  (draft->'appearance'=published->'appearance') as consistent_appearance
from public.sample_english_editor_pages where page_key in ('about','spirit','history') order by page_key;
